def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    pc = getv(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        if not dest or dest in act:
            old = nb.get('placed_count', 0)
            try:
                old = int(old)
            except Exception:
                old = 0
            nb['placed_count'] = old + 1
    wrong = bool(target and inv and 'nothing' not in inv and 'not carrying' not in inv and target not in inv)
    if wrong:
        nb['stage'] = 'wrong_inventory'
    elif target and act.startswith('put ') and target in act and 'you put' in obs and (not dest or dest in act):
        nb['stage'] = 'done'
    elif target and act.startswith('put ') and target in act and dest and dest not in act:
        nb['stage'] = 'wrong_inventory'
    elif target and act.startswith('take ') and target in act and 'you pick up' in obs:
        nb['stage'] = 'transform' if verb and not nb.get('transformed') else 'go_destination'
    elif target and act.startswith('put ') and target in act and dest and dest in act and 'you put' in obs:
        nb['stage'] = 'done'
    elif target and act.startswith('put ') and target in act and dest and dest not in act:
        nb['stage'] = 'wrong_inventory'
    elif target and act.startswith('put ') and target in act and (not dest or dest in act):
        nb['stage'] = 'done'
    elif target and act.startswith('take ') and target in act and 'you pick up' in obs:
        nb['stage'] = 'transform' if verb and not nb.get('transformed') else 'go_destination'
    elif target and act.startswith('take ') and target in act:
        nb['stage'] = 'take_target'
    elif target and verb and not nb.get('transformed'):
        nb['stage'] = 'transform'
    elif target and (not dest or dest in act or dest in obs or 'you are' in obs or 'facing' in obs):
        nb['stage'] = 'put_target'
    elif target and (not dest or dest in act or dest in obs or 'you are' in obs or 'facing' in obs):
        nb['stage'] = 'go_destination'
    elif target and (not dest or dest in act or dest in obs or 'you are' in obs or 'facing' in obs):
        nb['stage'] = 'find_target'
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    return None

