def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not target or not tt:
        return None
    stage = nb.get('stage', 'find_target')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target object. Do not place it as the goal item; recover and search for the requested ' + target + '.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target instead of other object types.'
    elif stage == 'transform' and verb and target:
        msg = 'Before final placement, use the admissible ' + verb + ' action on the ' + target + '. Do not put it at the destination yet.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' and use the admissible put action there.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the ' + dest + ' with the ' + target + '. Use the admissible put action for this destination.'
    elif stage == 'find_target' and target:
        msg = 'Search for the requested ' + target + '; do not place a different object type as the goal item.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

